#pragma once
static void testFreeze(const juce::File& root){
 auto dir=root.getChildFile("freeze");dir.createDirectory();Session s(dir);auto& hosted=s.engine.getDeviceManager().getHostedAudioDeviceInterface();te::HostedAudioDeviceInterface::Parameters params;params.sampleRate=48000;params.blockSize=128;params.inputChannels=0;params.outputChannels=2;hosted.initialise(params);hosted.prepareToPlay(48000,128);
 s.importAudio(root.getChildFile("source.wav"),0,0);juce::VST3PluginFormat format;juce::OwnedArray<juce::PluginDescription> types;format.findAllTypesForFile(types,juce::File(STUDIO_SOURCE_ROOT).getChildFile("build/editor/StudioTestGain_artefacts/Release/VST3/Studio Test Gain.vst3").getFullPathName());require(types.size()==1,"Freeze fixture scan failed");s.engine.getPluginManager().initialise();s.engine.getPluginManager().knownPluginList.addType(*types[0]);
 auto plugin=s.edit->getPluginCache().createNewPlugin(te::ExternalPlugin::xmlTypeName,*types[0]);auto* effect=dynamic_cast<te::ExternalPlugin*>(plugin.get());require(effect!=nullptr,"Freeze plugin creation failed");s.trackAt(0).pluginList.insertPlugin(plugin,0,nullptr);effect->initialiseFully();require(effect->getAudioPluginInstance()!=nullptr,"Freeze plugin load failed");effect->getAudioPluginInstance()->getParameters()[0]->setValueNotifyingHost(0.25f);effect->flushPluginStateToValueTree();
 auto original=s.clips()[0]->state.createCopy();int checks=0;float error=0;juce::AudioBuffer<float> reference;
 auto verify=[&](const char* name){auto output=dir.getChildFile(juce::String(name)+".wav");s.render(output);auto audio=readWave(output);if(reference.getNumSamples()==0)reference=audio;else for(int c=0;c<2;++c)for(int i=0;i<48000;++i)error=std::max(error,std::abs(audio.getSample(c,i)-reference.getSample(c,i)));require(error<1e-6f,"Frozen/unfrozen audio differs");++checks;};
 verify("before");s.save();s.setTrackFrozen(0,true);require(s.trackAt(0).isFrozen(te::Track::individualFreeze),"Track not frozen");verify("frozen");
 s.save();auto currentFile=s.projectFile;auto checkpoint=s.checkpoint();require(s.projectFile==currentFile,"Checkpoint changed current path");
 {auto coldRoot=dir.getChildFile("cold-runtime");coldRoot.createDirectory();Session cold(coldRoot);cold.engine.getPluginManager().initialise();cold.engine.getPluginManager().knownPluginList.addType(*types[0]);cold.openProject(checkpoint);require(cold.trackAt(0).isFrozen(te::Track::individualFreeze),"Cold load lost freeze");auto output=coldRoot.getChildFile("restored.wav");cold.render(output);auto data=readWave(output);for(int c=0;c<2;++c)for(int i=0;i<48000;++i)error=std::max(error,std::abs(data.getSample(c,i)-reference.getSample(c,i)));require(error<1e-6f,"Cold freeze differs");++checks;}
 auto userTemplate=dir.getChildFile("frozen-template.swtemplate");s.saveTemplate(userTemplate);auto templateXml=juce::XmlDocument::parse(userTemplate);require(templateXml&&templateXml->toString().indexOf("studioFreezeAsset")<0&&templateXml->toString().indexOf("freezePoint")<0,"Template retained freeze assets");++checks;
 plugin=nullptr;s.reopen();require(s.trackAt(0).isFrozen(te::Track::individualFreeze),"Frozen flag lost after reopen");verify("reopened");s.setTrackFrozen(0,false);require(!s.trackAt(0).isFrozen(te::Track::individualFreeze),"Track not unfrozen");verify("unfrozen");
 require(s.clips()[0]->state.isEquivalentTo(original),"Freeze changed original clip");auto* restored=s.trackAt(0).pluginList.findFirstPluginOfType<te::ExternalPlugin>();require(restored!=nullptr,"Unfreeze lost plugin");restored->initialiseFully();require(restored->getAudioPluginInstance()!=nullptr&&std::abs(restored->getAudioPluginInstance()->getParameters()[0]->getValue()-0.25f)<1e-7f,"Unfreeze lost parameter");++checks;
 s.save();s.reopen();verify("unfrozen-reopened");auto* report=new juce::DynamicObject;juce::var result(report);report->setProperty("checks",checks);report->setProperty("max_error",error);report->setProperty("physical_device_opened",false);dir.getChildFile("freeze-result.json").replaceWithText(juce::JSON::toString(result));
}
